    @MethodSource("rangeCases")
    @DisplayName("각 질문의 구간 합을 계산한다")
    void calculatesRangeSums(String name, long[] expected, int[] values, int[][] ranges) {
        assertArrayEquals(expected, ArraySolution05.solve(values, ranges), name);
