                        new int[]{-1_000_000, 0, 940, 1_000_000},
                        new int[][]{{1, 1}, {2, 2}, {3, 3}, {4, 4}, {1, 4}}),
                Arguments.of("합이 0인 구간과 질문 순서 유지", new long[]{0, 0, 3, -5},
                        new int[]{2, -2, 5, -5},
                        new int[][]{{1, 2}, {1, 4}, {2, 3}, {4, 4}})
