    @DisplayName("자식이 둘인 완전한 세 층과 원본 보존")
    void sumsCompleteThreeLevelsWithoutChangingInput() {
        int[] values = {10, 20, 30, 40, 50, 60, 70};
        int[] before = values.clone();

        long actual = TreeSolution01.solve(values);

        assertAll(
                () -> assertEquals(220L, actual),
